window.IMAGE_URLS = {
  "logo": "data:image/webp;base64,",
  "hero": "data:image/webp;base64,",
  "food": "data:image/webp;base64,",
  "portrait": "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=1600&q=85",
  "camera": "https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=1600&q=85",
  "fashion": "https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=1600&q=85"
};

document.querySelectorAll('[data-image-url]').forEach((el) => {
  const key = el.getAttribute('data-image-url');
  if (window.IMAGE_URLS[key]) el.src = window.IMAGE_URLS[key];
});
